  /* ===== ZOOM (UNCHANGED logic) ===== */
  function ASDSASDAApplyZoom(dir, steps) {
    try {
      if (typeof ϲ᠍ࡁ === "undefined") return;
      steps = steps || 1;
      var step = 0.1;
      var maxZ = 1.0;
      var minZ = -1.0;
      for (var s = 0; s < steps; s++) {
        var cur = ϲ᠍ࡁ[ᴉ２８];
        if (typeof cur !== "number") cur = 0;
        if (dir > 0) {
          if (cur >= maxZ) break;
          cur += step;
          if (cur > maxZ) cur = maxZ;
        } else {
          if (cur <= minZ) break;
          cur -= step;
          if (cur < minZ) cur = minZ;
        }
        ϲ᠍ࡁ[ᴉ２８] = cur;
      }
      ASDSASDA_MOD.zoom = ϲ᠍ࡁ[ᴉ２８];
    } catch (e) {}
  }

